const std::string key = make_uuid4();          // once per logical operation
http::request<http::string_body> req{http::verb::post, target, 11};
req.set("Idempotency-Key", key);
for (int attempt = 0; attempt < 3; ++attempt) {
    auto res = send(req);                      // same request, same key
    if (res) return *res;                      // std::optional<response>
    std::this_thread::sleep_for(backoff(attempt));
}
return std::unexpected(Outcome::Unknown);      // C++23 std::expected

